/* Traceability workbench; source-linked drafts, not institutional clinical approval. */
let knowledgeTab='tests',knowledgeResults=state.knowledgeLastRun?.release===FNKnowledge.release?state.knowledgeLastRun:null;
state.fieldProvenance??={};state.medicationReviews??=[];
protocolRelease.version='0.14';protocolRelease.scope+='; traceable order metadata and validation workbench';
TABS.push('Data provenance');
function knowledgeEngine(){return {assess,fnEligibility,draftPathways,cefepimeReference,proposedOrderCodes}}
function runKnowledgeTests(){knowledgeResults={at:new Date().toISOString(),release:FNKnowledge.release,results:FNKnowledge.cases.map(c=>FNKnowledge.evaluateCase(c,knowledgeEngine()))};state.knowledgeLastRun=knowledgeResults;save('Ran 15 synthetic expected-behavior cases; specialist adjudication pending')}
function dictionaryRows(){return assessmentFields.flatMap(([group,fields])=>fields.map(([key,label,type,...spec])=>{const unit=key.includes('×10')?'×10⁹/L (500 cells/µL = 0.5)':key.match(/\(([^)]+)\)/)?.[1]||'Not applicable';return {key,label,group,type,unit,allowed:type==='yesno'?['Yes','No','Unknown']:type==='select'?spec[0]:type==='number'?{min:spec[0],max:spec[1]}:'Text',requiredFor:group==='MASCC components'?'MASCC calculation':group==='Identity & presentation'?'Identity, FN and safety assessment':'Related candidate rule only',source:'Synthetic workbook or manually entered assessment; verify source per case',timestamp:'fieldProvenance[patientId][field].observedAt; absent means not supplied',missingBehavior:'Keep unknown; withhold dependent rule/reference or request review',owner:group.includes('Medication')?'Clinical pharmacy':'Clinical assessment owner',version:FNKnowledge.release}}))}
function refLink(key){const r=FNKnowledge.references[key];return r?.url?`<a href="${r.url}" target="_blank" rel="noopener">${esc(r.title)} · ${esc(r.version)}</a>`:esc(r?.title||key)}
function knowledgeWorkbench(){const tabs=[['tests','15 test cases'],['dictionary','Data dictionary'],['rules','Rule register'],['medications','Medication review']];return `<section class="panel" style="margin-bottom:20px"><div class="sectiontitle"><div><h2>Validation & knowledge</h2><p>${FNKnowledge.release} · synthetic cases and reviewable evidence</p></div><button class="btn" onclick="exportKnowledge()">Export knowledge package</button></div><div class="actions">${tabs.map(([k,l])=>`<button class="btn ${knowledgeTab===k?'primary':''}" onclick="knowledgeTab='${k}';render()">${l}</button>`).join('')}</div>${knowledgeTab==='tests'?knowledgeTestView():knowledgeTab==='dictionary'?dictionaryView():knowledgeTab==='rules'?ruleView():medicationView()}</section>`}
function knowledgeTestView(){return `<p>Author-defined expected behavior, not a clinically adjudicated gold standard. Manual MASCC expectations, expected modules and safety behavior are stored separately from the actual rule calculations. No automatic primary treatment pathway is claimed.</p><div class="actions"><button class="btn primary" onclick="runKnowledgeTests()">Run 15 cases</button><button class="btn" onclick="exportKnowledgeResults()" ${!knowledgeResults?'disabled':''}>Export test report</button></div>${knowledgeResults?`<p role="status"><b>${knowledgeResults.results.filter(r=>r.pass).length}/15 passed</b> · ${fmt(knowledgeResults.at)} · ${esc(knowledgeResults.release)}. Specialist review remains pending.</p>`:'<p>Not run in this session. Run tests to compare current code with stored expectations.</p>'}<div class="knowledge-scroll"><table><thead><tr><th>Case</th><th>Expected</th><th>Actual / result</th><th>Inspect</th></tr></thead><tbody>${FNKnowledge.cases.map(c=>{const r=knowledgeResults?.results.find(x=>x.id===c.id);return `<tr><td>${c.id} · ${esc(c.title)}</td><td>${esc(knowledgeSummary(c.expected))}</td><td>${r?`<span class="pill ${r.pass?'':'red'}">${r.pass?'PASS':'DIFFERENCE'}</span><br>${esc(knowledgeSummary(r.actual))}`:'Not run'}</td><td><button class="btn" onclick="inspectKnowledgeCase('${c.id}')">Details</button></td></tr>`}).join('')}</tbody></table></div>`}
function inspectKnowledgeCase(id){const c=FNKnowledge.cases.find(c=>c.id===id),r=knowledgeResults?.results.find(r=>r.id===id);openDialog('Case '+id+' · '+c.title,`<p>${esc(c.why)}</p><p>Review status: ${esc(c.reviewStatus)}</p><h3>Expected</h3><pre style="white-space:pre-wrap">${esc(JSON.stringify(c.expected,null,2))}</pre><h3>Actual</h3><pre style="white-space:pre-wrap">${esc(JSON.stringify(r||'Not run',null,2))}</pre><details><summary>Input fixture</summary><pre style="white-space:pre-wrap">${esc(JSON.stringify(c.patient,null,2))}</pre><p>Allergy fixture: ${esc(c.allergy)} · ANC unit ${esc(c.unit)}</p></details><button class="btn" onclick="closeDialog()">Close</button>`)}
function exportKnowledgeResults(){if(knowledgeResults)download('FN_15_SYNTHETIC_test_report.json',{...knowledgeResults,clinicalAdjudication:'PENDING',cases:FNKnowledge.cases})}
function dictionaryView(){const rows=dictionaryRows();return `<p>${rows.length} assessment fields. ANC canonical unit is ×10⁹/L; units must be normalized before entry. Form save time is not an observation time. Per-field source and observed time can be recorded under Patient → Data provenance.</p><div class="knowledge-scroll"><table><thead><tr><th>Field / type</th><th>Unit / allowed</th><th>Required for</th><th>Missing and provenance</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.label)}<br><small>${esc(r.key)} · ${esc(r.type)}</small></td><td>${esc(r.unit)}<br>${esc(JSON.stringify(r.allowed))}</td><td>${esc(r.requiredFor)}</td><td>${esc(r.missingBehavior)}<details><summary>Source and timestamp policy</summary>${esc(r.source)}<br>${esc(r.timestamp)}</details></td></tr>`).join('')}</tbody></table></div>`}
function ruleView(){return `<p>Priority numbers describe prototype review order. Candidate modules can overlap; they do not select an approved primary regimen. All rules below remain drafts. Source locations are sections or recommendations; unavailable page mappings are not invented.</p><div class="knowledge-scroll"><table><thead><tr><th>Rule / priority</th><th>Condition → action</th><th>Source / location</th><th>Owner / approval</th></tr></thead><tbody>${FNKnowledge.rules.map(r=>`<tr><td>${r.id} · ${r.priority}<br>${r.version}</td><td>${esc(r.condition)}<br>→ ${esc(r.action)}</td><td>${refLink(r.source)}<br>${esc(r.location)}</td><td>${esc(r.owner)}<br>${esc(r.approval)}</td></tr>`).join('')}</tbody></table></div>`}
function medicationView(){return `<p>Structured medication review register. Only the existing gated cefepime label reference has encoded dose calculations. Other rows are explicit review tasks. Entered review notes do not create prescriptions or change clinical approval.</p><div class="knowledge-scroll"><table><thead><tr><th>Drug / source</th><th>Dose, route and interval</th><th>Renal / allergy / alternative</th><th>Review</th></tr></thead><tbody>${FNKnowledge.medicationReview.map(m=>{const r=state.medicationReviews.find(r=>r.drugId===m.id);return `<tr><td>${esc(m.drug)}<br>${refLink(m.source)}</td><td>${esc(m.dose)}<br>${esc(m.route)}<br>${esc(m.interval)}<details><summary>Duration / reassessment</summary>${esc(m.review)}</details></td><td>${esc(m.renal)}<br>${esc(m.allergy)}<br>${esc(m.alternative)}</td><td>${esc(m.status)}<br>${r?esc(r.role)+' · '+esc(r.reviewer)+' · '+fmt(r.at):'No review recorded'}<button class="btn" onclick="openMedicationReview('${m.id}')">Record review</button>${r?`<details><summary>Latest review</summary><p>${esc(r.note)}</p><p>Dose proposal: ${esc(r.dose||'Not supplied')}<br>Route / interval: ${esc(r.route)} / ${esc(r.interval)}<br>Renal / allergy / alternatives: ${esc(r.safety)}<br>Source location: ${esc(r.source)}</p></details>`:''}</td></tr>`}).join('')}</tbody></table></div><details><summary>Medication review history</summary>${state.medicationReviews.map(r=>`<p>${esc(r.drugId)} · ${esc(r.role)} · ${esc(r.reviewer)} · ${fmt(r.at)} · Draft review only<br>${esc(r.note)}</p>`).join('')||'No reviews yet'}</details>`}
function openMedicationReview(id){const m=FNKnowledge.medicationReview.find(m=>m.id===id);openDialog('Medication review · '+m.drug,`<p>This records a draft review, not clinical approval. No new dosing rule will execute from these notes.</p><form onsubmit="event.preventDefault();saveMedicationReview('${id}',this)"><label class="field">Role<select name="role"><option>Clinical pharmacy</option><option>Oncology / infectious diseases</option></select></label><label class="field">Reviewer label<input name="reviewer" required maxlength="100"></label><label class="field">Source and exact section / table<input name="source" required maxlength="400"></label><div class="grid2"><label class="field">Draft dose proposal or outstanding gap<input name="dose" required maxlength="300"></label><label class="field">Route<input name="route" required maxlength="100"></label><label class="field">Interval and duration / reassessment<input name="interval" required maxlength="300"></label><label class="field">Renal, allergy, contraindication and alternative review<textarea name="safety" required maxlength="800"></textarea></label></div><label class="field">Review findings and next action<textarea name="note" required maxlength="800"></textarea></label><button class="btn primary" type="submit">Save draft review</button><button type="button" class="btn" onclick="closeDialog()">Cancel</button></form>`)}
function saveMedicationReview(id,form){const r=Object.fromEntries(new FormData(form));if(!FNKnowledge.medicationReview.some(m=>m.id===id)||!['Clinical pharmacy','Oncology / infectious diseases'].includes(r.role)||['reviewer','source','dose','route','interval','safety','note'].some(k=>!r[k]?.trim()))return;state.medicationReviews.unshift({...r,drugId:id,at:new Date().toISOString(),release:FNKnowledge.release,status:'Draft review only'});closeDialog();save('Recorded medication draft review '+id+' by '+r.role)}
function exportKnowledge(){download('FN_knowledge_package_0.14.json',{release:FNKnowledge.release,clinicalApproval:'PENDING',dataDictionary:dictionaryRows(),rules:FNKnowledge.rules,references:FNKnowledge.references,syntheticCases:FNKnowledge.cases,medicationRegister:FNKnowledge.medicationReview,medicationReviews:state.medicationReviews,latestTestRun:knowledgeResults,storage:'Clinical review records remain browser-local; remote backend currently covers escalation only'})}
function provenanceView(){const pid=id(selected),rows=state.fieldProvenance[pid]||{};return `<section class="panel"><h2>Field source and observation time</h2><p>Assessment save time does not establish when a measurement was taken. Original workbook timestamps were not supplied. Record provenance only when known; blank remains unknown.</p><form onsubmit="event.preventDefault();saveFieldProvenance(this)"><label class="field">Assessment field<select name="field">${dictionaryRows().map(r=>`<option value="${esc(r.key)}">${esc(r.label)}</option>`).join('')}</select></label><label class="field">Source<input name="source" required maxlength="200" placeholder="Synthetic scenario / workbook / manually entered"></label><label class="field">Observation time if known<input type="datetime-local" name="observedAt"></label><label class="field">Evidence / reason<textarea name="note" required maxlength="600"></textarea></label><p id="provenanceError" role="alert"></p><button class="btn primary" type="submit">Save provenance</button></form><div class="knowledge-scroll"><table><thead><tr><th>Field</th><th>Source</th><th>Observed / recorded</th><th>Evidence</th></tr></thead><tbody>${Object.entries(rows).map(([key,r])=>`<tr><td>${esc(key)}</td><td>${esc(r.source)}</td><td>${r.observedAt?fmt(r.observedAt):'Unknown'} / ${fmt(r.recordedAt)}</td><td>${esc(r.note)}</td></tr>`).join('')}</tbody></table></div><button class="btn" onclick="download('FN-field-provenance.json',state.fieldProvenance[id(selected)]||{})">Export provenance</button></section>`}
function saveFieldProvenance(form){const f=Object.fromEntries(new FormData(form)),at=f.observedAt?new Date(f.observedAt):null;if(!dictionaryRows().some(r=>r.key===f.field)||!f.source?.trim()||!f.note?.trim()||at&&(!Number.isFinite(at.getTime())||at.getTime()>Date.now())){$('#provenanceError').textContent='Enter source and evidence; observation time must be valid and not in the future.';return}const pid=id(selected);state.fieldProvenance[pid]??={};const prior=state.fieldProvenance[pid][f.field];state.fieldProvenance[pid][f.field]={source:f.source.trim(),note:f.note.trim(),observedAt:at?.toISOString()||null,recordedAt:new Date().toISOString(),prior:prior||null};save('Updated field provenance: '+f.field,pid)}
const detailBeforeKnowledge=detail;detail=function(){let h=detailBeforeKnowledge();if(selected&&patientTab==='Data provenance')h+=provenanceView();return h};
const renderBeforeKnowledge=render;render=function(){renderBeforeKnowledge();if(view==='Scope & evidence')$('#app').insertAdjacentHTML('afterbegin',knowledgeWorkbench())};

function knowledgeSummary(x){if(x.inputError)return 'Reject invalid input / unit';return [x.fn==='Numeric criteria met'?'FN criteria met':x.fn==='Incomplete assessment'?'FN incomplete':'FN not established','MASCC '+(x.score??'unknown'),x.risk+' risk',(x.modules||[]).join(' + ')||'No confirmed FN modules',x.medBlocked?'Dose reference withheld':'Limited dose reference available',x.maintenance||'',x.orderCodes?x.orderCodes.length+' proposed review items':''].filter(Boolean).join(' · ')}

for(const row of scopeCoverage){if(row[0]==='Sources, versions and governance'){row[1]='Traceable draft registry';row[2]='Versioned rule/source register, conditional order metadata and demo review. Institutional clinical approval remains pending.'}if(row[0]==='Hospital integration / roles / sync'){row[1]='Partial escalation backend';row[2]='Authenticated account-scoped server roster and escalation records implemented; gateway disconnected. Clinical case and knowledge review records remain browser-local; no EHR/LIS or shared clinical roles.'}}
